/**
 * ROK-1837 L3 — the contract fixture `valheim-link/v1/fixtures/
 * map-shared-layer.json`, inlined: the runtime image does not ship the
 * contract fixtures. A unit spec pins these bytes to the fixture file.
 * Its placeholder `baseMap.sha256` (`aaaa…`) is NOT carried — the seed
 * writes a real PNG and stores its hash instead.
 */
import type { ValheimMapMessage } from '@raid-ledger/contract';

export const MAP_FIXTURE_IDENTITY = {
  steamId: '76561198000000001',
  playerId: '1000000000000001',
  worldUid: '1234567890123',
} as const;

export const MAP_FIXTURE_GRID = { textureSize: 2048, pixelSizeMetres: 12 };

/** The placeholder hash the fixture ships for its base map. */
export const MAP_FIXTURE_PLACEHOLDER_SHA256 =
  'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';

const bitset = (data: string) => ({
  encoding: 'gzip+base64-bitset-lsb0' as const,
  width: 2048,
  height: 2048,
  data,
});

export const MAP_FIXTURE_EXPLORED: ValheimMapMessage['explored'] = bitset(
  '',
);

export const MAP_FIXTURE_SHARED_EXPLORED: NonNullable<
  ValheimMapMessage['sharedExplored']
> = bitset(
  '',
);

